layout(color) uniform half4 amzp_keyColor;
uniform float amzp_threshold;
uniform float amzp_feather;
uniform float amzp_defringe;
uniform float amzp_invert;


        void amzRender() {

             float3x3 rgb2yuv = float3x3(
                 0.299,     0.587,    0.114,
                -0.14713,  -0.28886,  0.436,
                 0.615,    -0.51499, -0.10001
            );

             float3x3 yuv2rgb = float3x3(
                1.0,  0.0,      1.13983,
                1.0, -0.39465, -0.58060,
                1.0,  2.03211,  0.0
            );

            float3 keyYUV = amzp_keyColor.rgb * rgb2yuv;
            float4 texColor = amzTexture(0,amzScreenNorm());
            float3 texYUV = (texColor.a <= 0.0 ? float3(0.0) : texColor.rgb / texColor.a) * rgb2yuv;

            float dist = length((keyYUV - texYUV) * float3(0.25,1.0,1.0));

            float alpha = smoothstep( amzp_threshold-amzp_feather/2., amzp_threshold+amzp_feather/2., dist );
            if((amzp_invert>0.5)) alpha = 1.-alpha;
            if((amzp_defringe>0.5)) texColor -= (amzp_keyColor*(1.0-alpha));
            float2 halfFragSize = float2(1.0)/getTexSize((screen.zw/1.0))/2.;
            if(amzLayerNorm().x <= halfFragSize.x || amzLayerNorm().x >= 1.0 - halfFragSize.x || amzLayerNorm().y <= halfFragSize.y || amzLayerNorm().y >= 1.0 - halfFragSize.y) {
                alpha = 0.0;
            }
            amzOutput = float4(texColor.rgb,1.0) * alpha*texColor.a;
        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

